// Récupère le texte de la commande (le bot envoie le corps JSON).
const body = $json.body ?? $json;
const text = String(body.text ?? '');
// Enlève le verbe (/liste-membre) et les guillemets éventuels.
const liste = text.replace(/^\/\S+\s*/, '').trim().replace(/^["']|["']$/g, '');
return [{ json: { liste } }];

// Construit la réponse à partir des lignes Grist.
const records = $json.records ?? [];
const noms = records
  .map(r => {
    const f = r.fields ?? {};
    const nom = String(f.Nom ?? '').trim();
    const mxid = String(f.MatrixUserId ?? '').trim();
    const fallback = mxid.replace(/^@/, '').split(':')[0] ?? mxid;
    return { nom: nom || fallback, mxid };
  })
  .filter(m => m.mxid.length > 0);
const liste = $('Parse').item.json.liste;
let message, reaction;
if (!liste) {
  message = '❌ Usage : `/liste-membre <nom>`';
  reaction = '❌';
} else if (noms.length === 0) {
  message = `📭 Aucune liste **${liste}** (ou elle est vide).`;
  reaction = '📭';
} else {
  message = `📋 Liste **${liste}** (${noms.length} membre${noms.length > 1 ? 's' : ''}) : ${noms.map(m => m.nom).join(', ')}`;
  reaction = '📋';
}
return [{ json: { message, reaction } }];
